void Delay500ms() {   // STC-ISP延时计算器生成（12MHz, Y1指令集）
    unsigned char i, j, k;
    _nop_();
    i = 4; j = 205; k = 187;
    do { do { while (--k); } while (--j); } while (--i);
}

