unsigned char LEDNum = 0;  // 全局变量（main外定义）

void main() {
    while(1) {
        // K1 左移
        if (P3_1 == 0) {
            Delay(20); while(P3_1==0); Delay(20);
            LEDNum++;
            if (LEDNum >= 8) LEDNum = 0;   // 到头归零
            P2 = ~(0x01 << LEDNum);
        }
        // K2 右移
        if (P3_0 == 0) {
            Delay(20); while(P3_0==0); Delay(20);
            if (LEDNum == 0) LEDNum = 7;   // 无符号下溢保护
            else LEDNum--;
            P2 = ~(0x01 << LEDNum);
        }
    }
}

