void Timer0Init() {
    TMOD &= 0xF0;   // 高4位不变，清低4位（不影响T1）
    TMOD |= 0x01;   // T0，模式1（16位），定时模式
    TL0 = 0x18;     // 初值低字节
    TH0 = 0xFC;     // 初值高字节（64536 = 1ms@12MHz）
    TF0 = 0; TR0 = 1;   // 清溢出标志，启动
    ET0 = 1; EA = 1;    // 打开T0中断、总中断
}

void Timer0() interrupt 1 {
    static unsigned int T0Count = 0;
    TL0 = 0x18; TH0 = 0xFC;   // 重装初值（关键！）
    T0Count++;
    if (T0Count >= 1000) {    // 累计1000次 = 1秒
        T0Count = 0;
        P2_0 = ~P2_0;         // 每秒做一件事
    }
}

#include <REGX52.H>

void UART_Init() {
    SCON = 0x40;                // 方式1(8位UART), 禁止接收
    TMOD &= 0x0F; TMOD |= 0x20; // T1 模式2: 8位自动重装
    TH1 = TL1 = 0xF3;           // 波特率初值(由STC-ISP计算器按4800/加倍生成)
    TR1 = 1;                    // 启动T1作波特率发生器(不开中断)
}

void UART_SendByte(unsigned char b) {
    SBUF = b;                   // 写入即发送
    while (TI == 0);            // 等发送完成
    TI = 0;                     // 软件清零发送标志
}

void _74HC595_WriteByte(unsigned char dat) {
    for (int i = 0; i < 8; i++) {
        SER = dat >> 7;        // 取最高位
        dat <<= 1;
        SRCLK = 1; SRCLK = 0;  // 上升沿移位
    }
    RCLK = 1; RCLK = 0;        // 上升沿锁存输出
}

// 74HC595 写一字节(高位先出)
void _74HC595_WriteByte(unsigned char dat) {
    for (int i = 0; i < 8; i++) {
        SER = dat & (0x80 >> i);   // 依次取最高位→最低位
        SRCLK = 1; SRCLK = 0;      // 上升沿移位
    }
    RCLK = 1; RCLK = 0;            // 上升沿锁存输出
}
