void DS1302_WriteByte(unsigned char cmd, unsigned char dat) {
    DS1302_CE = 0; DS1302_SCLK = 0; DS1302_CE = 1;
    for (int i = 0; i < 8; i++) { DS1302_IO = cmd & (0x01<<i); DS1302_SCLK = 1; DS1302_SCLK = 0; }
    for (int i = 0; i < 8; i++) { DS1302_IO = dat & (0x01<<i); DS1302_SCLK = 1; DS1302_SCLK = 0; }
    DS1302_CE = 0;
}
unsigned char DS1302_ReadByte(unsigned char cmd) {
    unsigned char dat = 0;
    DS1302_CE = 0; DS1302_SCLK = 0; DS1302_CE = 1;
    for (int i = 0; i < 8; i++) { DS1302_IO = cmd & (0x01<<i); DS1302_SCLK = 1; DS1302_SCLK = 0; }
    DS1302_IO = 1;   // 释放总线, 交还DS1302
    for (int i = 0; i < 8; i++) {
        DS1302_SCLK = 1; DS1302_SCLK = 0;
        if (DS1302_IO) dat |= (0x01 << i);  // 下降沿后读IO
    }
    DS1302_CE = 0; return dat;
}
