float DS18B20_ReadTemp(){
    unsigned char tL, tM; unsigned int temp;
    DS18B20_ConvertT();              // 启动转换
    OneWire_Init();
    OneWire_SendByte(0xCC);          // 跳过ROM
    OneWire_SendByte(0xBE);          // 读暂存器
    tL = OneWire_ReceiveByte();
    tM = OneWire_ReceiveByte();
    temp = (tM << 8) | tL;           // 合成补码
    return (int16)temp / 16.0;      // 转摄氏温度
}

