unsigned int XPT2046_ReadAD(unsigned char cmd){
    unsigned int ad = 0;
    XPT2046_CS = 0; XPT2046_DCLK = 0;
    for(i=0;i<8;i++){            // 发控制字
        XPT2046_DIN = cmd & (0x80 >> i);
        XPT2046_DCLK = 1; XPT2046_DCLK = 0;
    }
    for(i=0;i<16;i++){           // 读16位
        XPT2046_DCLK = 1; XPT2046_DCLK = 0;
        ad <<= 1; if(XPT2046_DOUT) ad |= 1;
    }
    XPT2046_CS = 1;
    return (cmd & 0x04) ? ad >> 8 : ad >> 4;  // 8位/12位
}

// ===== 外部中断0 初始化（Int0.c）：红外接收头 OUT 接 P3.2 =====
void Int0_Init(void)
{
    IT0 = 1;   // 1=下降沿触发(红外解码用这个)  0=低电平触发
    IE0 = 0;   // 清中断标志位
    EX0 = 1;   // 允许外部中断0
    EA  = 1;   // 开总中断
    PX0 = 1;   // 高优先级, 可打断别的中断保证解码计时精准
}

// ===== 定时器0 当“计时器”用（Timer0.c），不进中断 =====
void Timer0_SetCounter(unsigned int value){ TH0 = value >> 8; TL0 = value & 0xFF; }
unsigned int Timer0_GetCounter(void){ return (TH0 << 8) | TL0; }
void Timer0_Run(bit flag){ TR0 = flag; }   // 1启动计时, 0停止

// ===== 红外解码状态机（在 INT0 中断里，IR.c）=====
void Int0_Routine(void) interrupt 0
{
    if (IR_State == 0)            // 空闲: 第一次下降沿, 开始计时
    {
        Timer0_SetCounter(0);
        Timer0_Run(1);
        IR_State = 1;
    }
    else if (IR_State == 1)       // 判断 Start 还是 Repeat
    {
        IR_Time = Timer0_GetCounter() / 1.085;  // 换算成微秒
        Timer0_SetCounter(0);
        if (IR_Time > 13000 && IR_Time < 14000) IR_State = 2;        // 起始 9ms+4.5ms≈13500us
        else if (IR_Time > 10750 && IR_Time < 11750) { IR_RepeatFlag = 1; IR_State = 0; Timer0_Run(0); } // Repeat≈11250us
    }
    else if (IR_State == 2)       // 解码 32 位数据
    {
        IR_Time = Timer0_GetCounter() / 1.085;
        Timer0_SetCounter(0);
        if (IR_Time > 620 && IR_Time < 1620)         // 逻辑0: 560+560≈1120us
            IR_Data[IR_pData / 8] &= ~(0x01 << (IR_pData % 8));
        else if (IR_Time > 1750 && IR_Time < 2750)    // 逻辑1: 560+1690≈2250us
            IR_Data[IR_pData / 8] |=  (0x01 << (IR_pData % 8));
        else { IR_State = 1; IR_pData = 0; }          // 出错, 重新搜起始
        IR_pData++;
        if (IR_pData >= 32)        // 收满32位, 校验地址与反码
        {
            IR_pData = 0;
            if ((IR_Data[0] ^ IR_Data[1]) == 0xFF) { IR_Address = IR_Data[0]; IR_Command = IR_Data[2]; IR_DataFlag = 1; }
            IR_State = 0; Timer0_Run(0);
        }
    }
}
